-- Produs nou: trafalet magic cu rezervor și vopsea lavabilă albă (Helpship; stoc 0 până ajunge marfa la depozit)
INSERT OR IGNORE INTO products (slug, title, subtitle, description, price, compare_at_price, cost_price, sku, stock, track_stock, weight_g, images, benefits, faq, bundles, badge, category, active, featured, sort)
VALUES ('trafalet-magic-cu-rezervor', 'Trafalet magic cu rezervor și vopsea albă', 'Retușezi pereții în câteva minute, fără găleată și fără mizerie',
 'Un trafalet cu rezervor de vopsea încorporat, gândit pentru retușuri rapide pe pereți, fără găleată, fără tăviță și fără pensule. Apeși ușor pe recipient, vopseaua ajunge direct în rolă și o întinzi uniform pe perete.

În pachet primești recipientul cu 500 g de vopsea lavabilă albă, pe bază de apă, și capul de trafalet cu rolă detașabilă. Este potrivit pentru pete, urme de murdărie, desene de copii pe pereți, mici zgârieturi sau colțuri cojite.

Rola se scoate și se spală cu apă după folosire, iar recipientul poate fi reumplut cu orice vopsea lavabilă pe bază de apă, așa că îl poți folosi și la următoarele retușuri.',
 6900, 11900, 1210, 'CHI-TRF-01', 0, 1, 650,
 '["/img/trafalet-magic-1.jpg", "/img/trafalet-magic-2.jpg", "/img/trafalet-magic-3.jpg", "/img/trafalet-magic-4.jpg", "/img/trafalet-magic-5.jpg", "/img/trafalet-magic-6.jpg", "/img/trafalet-magic-7.jpg"]', '["Vopsea lavabilă albă inclusă: 500 g, gata de folosit", "Fără găleată, tăviță sau pensule: vopseaua vine direct în rolă", "Rolă detașabilă, se spală cu apă și se refolosește", "Recipient reîncărcabil cu orice vopsea pe bază de apă"]', '[{"q": "Ce primesc în colet?", "a": "Recipientul cu 500 g de vopsea lavabilă albă și capul de trafalet cu rolă detașabilă."}, {"q": "Pentru ce suprafețe este potrivit?", "a": "Pentru retușuri pe pereți și tavane vopsite în alb: pete, urme de murdărie, desene, mici zgârieturi sau zone cojite. Pentru zugrăvirea unei camere întregi ai nevoie de mai multă vopsea și de un trafalet clasic."}, {"q": "Acoperă petele de mucegai?", "a": "Vopseaua acoperă petele, dar nu tratează cauza. Curăță și tratează mai întâi mucegaiul cu o soluție dedicată, lasă peretele să se usuce complet și abia apoi aplică vopseaua."}, {"q": "Câte straturi trebuie să dau?", "a": "De obicei unul sau două. Pentru al doilea strat, lasă primul să se usuce 2–4 ore."}, {"q": "Cum îl curăț după folosire?", "a": "Scoate capul de trafalet și spală bine rola cu apă, ca vopseaua să nu se usuce pe ea. Recipientul se închide cu capacul."}, {"q": "Este sigur în casă?", "a": "Vopseaua este pe bază de apă. Ca orice vopsea, ține recipientul departe de copii și animale, aerisește camera și nu aplica pe pereți umezi sau la temperaturi sub 5°C."}, {"q": "Cât durează livrarea?", "a": "24–48 de ore lucrătoare de la confirmarea comenzii. Plătești la livrare."}]', '[{"qty": 1, "pct": 0, "label": ""}, {"qty": 2, "pct": 10, "label": "Cel mai ales"}, {"qty": 3, "pct": 15, "label": "Cea mai bună ofertă"}]', 'Nou', 'Casă', 1, 0, 5);
UPDATE products SET sections = '[{"title": "Vopsea și trafalet, într-un singur produs", "image": "/img/trafalet-magic-3.jpg", "text": "Recipientul cu vopsea se înșurubează direct sub rolă. Apeși ușor pe el și vopseaua ajunge exact cât trebuie, fără să mai torni în tăviță.\n\nRola se detașează și se spală, iar recipientul îl poți reumple cu orice vopsea lavabilă pe bază de apă."}, {"title": "Gata de folosit în câteva minute", "image": "/img/trafalet-magic-4.jpg", "text": "Cureți și usuci suprafața, agiți bine recipientul, îl deschizi și atașezi rola. Apeși ușor până curge vopseaua și rulezi peste zona dorită.\n\nDacă vrei un alb mai intens, după 2–4 ore aplici încă un strat."}, {"title": "Pereți ca noi, fără zugrăveală", "image": "/img/trafalet-magic-5.jpg", "text": "Pete, urme de mâini, desene ale copiilor sau colțuri cojite dispar sub un strat nou de alb, fără să zugrăvești toată camera.\n\nPentru petele de mucegai, tratează mai întâi zona cu o soluție dedicată și las-o să se usuce, apoi acoperă cu vopsea."}, {"title": "Pentru orice casă cu copii", "image": "/img/trafalet-magic-6.jpg", "text": "Desenele pe pereți nu mai sunt o problemă: le acoperi în câteva minute, fără mizerie și fără să muți mobila.\n\nE ușor de ținut în mână și de depozitat, gata pentru următorul retuș."}]', specs = '[{"k": "Tip", "v": "Trafalet cu rezervor de vopsea încorporat"}, {"k": "Vopsea inclusă", "v": "500 g vopsea lavabilă albă, pe bază de apă"}, {"k": "Conține", "v": "Recipient reîncărcabil și cap de trafalet cu rolă detașabilă"}, {"k": "Dimensiuni", "v": "21 × 10,5 × 8,5 cm"}, {"k": "Uscare între straturi", "v": "2–4 ore"}, {"k": "Utilizare", "v": "Retușuri pe pereți și tavane albe"}, {"k": "Temperatura minimă", "v": "5°C, nu se aplică pe pereți umezi"}, {"k": "Valabilitate", "v": "24 de luni de la data de producție (pe recipient)"}, {"k": "Atenție", "v": "Nu lăsa la îndemâna copiilor și animalelor"}]', fulfillment = 'helpship', length_cm = 22, width_cm = 12, height_cm = 10
WHERE slug = 'trafalet-magic-cu-rezervor';
